const VALLEY_DATA={id:"valley-of-flowers",name:"Valley of Flowers National Park",location:"Chamoli District, Garhwal Himalayas, Uttarakhand",established:1982,unesco:"Inscribed as a UNESCO World Heritage Site in 2005",area:"87.5 km²",altitude:"3,350 m – 3,650 m",coordinates:{lat:30.728,lng:79.605},bestSeason:"Mid-June to September (peak bloom: July–August)",quickStats:[{label:"Alpine Flower Species",value:"600+",icon:"🌸"},{label:"UNESCO World Heritage",value:"2005",icon:"🏛️"},{label:"Faunal Species",value:"200+",icon:"🐾"},{label:"Trek Difficulty",value:"Moderate",icon:"🥾"}],ecology:{title:"A Valley Carpeted in Alpine Blooms",description:"Nestled between the peaks of the Garhwal Himalaya at the head of the Bhyundar Gorge, the Valley of Flowers bursts into a spectacular carpet of colour during the brief monsoon bloom. Over 600 species of flowering plants, including the iconic Himalayan Blue Poppy (Meconopsis), Cobra Lily, and the sacred Brahma Kamal, cover the valley floor in an extraordinary seasonal display.",facts:["Declared a National Park in 1982 and a UNESCO World Heritage Site in 2005.","Lies within the wider Nanda Devi Biosphere Reserve.","The valley stays snowbound for most of the year and opens only between June and September.","Home to an exceptional concentration of endemic Himalayan flora and fauna."]},flowers:[{name:"Himalayan Blue Poppy (Meconopsis)",status:"Rare & Iconic",desc:"The elusive blue poppy is the crown jewel of the valley, thriving in damp alpine meadows and shady crevices.",icon:"💙"},{name:"Brahma Kamal (Saussurea obvallata)",status:"Sacred & State Flower",desc:"Uttarakhand’s state flower, a large, fragrant bloom that opens under the full moon and is offered at shrines.",icon:"🪷"},{name:"Cobra Lily (Arisaema)",status:"Endemic Alpine",desc:"A striking perennial with a cobra-like hood and long purple tongue, found in shady, moist ravines.",icon:"🌿"},{name:"Pink & Yellow Primulas",status:"Carpet-forming",desc:"Vast swathes of primulas, saxifrages, and potentillas paint the meadows in pink, yellow, and purple hues.",icon:"🌷"}],wildlife:[{name:"Snow Leopard",status:"Endangered",desc:"The elusive apex predator roams the high crags surrounding the valley.",icon:"🐆"},{name:"Himalayan Musk Deer",status:"Endangered",desc:"A shy, solitary deer whose musk gland made it a target for poachers.",icon:"🦌"},{name:"Red Panda",status:"Endangered",desc:"The arboreal bamboo-eater haunts the dense temperate forests below the valley.",icon:"🐼"},{name:"Blue Sheep (Bharal)",status:"Vulnerable",desc:"Cliff-dwelling caprines graze on the steep grass slopes above the valley floor.",icon:"🐐"}],trekkingRoutes:[{id:"ghangaria",name:"Govindghat – Ghangaria",timing:"14 km · 2 days",desc:"The approach trek winds up the Alaknanda valley through cedar and birch forests to the trek base camp of Ghangaria.",highlight:"Starting point for both Valley of Flowers and Hemkund Sahib."},{id:"valley-loop",name:"Ghangaria – Valley Core Loop",timing:"6–7 km · Full day",desc:"A gentle loop from Ghangaria into the flower meadows, crossing the Pushpavati river and ascending to the valley overlooks.",highlight:"Best views of the Himalayan Blue Poppy colonies."},{id:"hemkund",name:"Hemkund Sahib Summit",timing:"6 km · 4 hours",desc:"A steep climb to the glacial Sikh shrine at 4,329 m, passing waterfalls, moraines, and rocky terrain.",highlight:"Panoramic views of Nanda Devi and Saptrishi peaks."},{id:"ghangaria-exit",name:"Descent via Bhyundar Gorge",timing:"14 km · 1 day",desc:"Return trek through the dramatic gorge with sightings of langurs, monals, and mixed broadleaf forests.",highlight:"Perfect for birdwatching on the return leg."}],mapHotspots:[{id:"pushpavati",name:"Pushpavati River",desc:"The glacier-fed stream that threads through the valley, nourishing the flower meadows.",x:350,y:420},{id:"ghangaria",name:"Ghangaria Base",desc:"The trek base camp and gateway to the valley at 3,050 m.",x:170,y:340},{id:"meadow",name:"Main Flower Meadow",desc:"The densest carpets of alpine blooms along the valley floor.",x:520,y:300},{id:"hemkund",name:"Hemkund Sahib",desc:"The glacial Sikh shrine atop a cirque lake at 4,329 m.",x:730,y:130}],gallery:[{src:"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80",caption:"Alpine meadows of the Valley of Flowers"},{src:"https://images.unsplash.com/photo-1516585427167-9f4af4d65753?auto=format&fit=crop&w=800&q=80",caption:"Himalayan Blue Poppy (Meconopsis)"},{src:"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80",caption:"Snow-capped Garhwal peaks"},{src:"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80",caption:"Monsoon bloom across the valley floor"}]};